+var express = require('../');
+var request = require('supertest');
+
+describe('Router with malformed percent encoding', function () {
+  it('should gracefully fallback when decodeURIComponent throws URIError', function (done) {
+    var app = express();
+    app.get('/user/:name', function (req, res) {
+      res.send(req.params.name);
+    });
+
+    request(app)
+      .get('/user/%E0%A4%A')
+      .expect(200)
+      .expect('%E0%A4%A', done);
+  });
+});
